ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'figs/differences'
OUT.mkdir(parents=True, exist_ok=True)
family = 'STIXGeneral' if any(f.name == 'STIXGeneral' for f in fm.fontManager.ttflist) else 'STIXGeneral'
plt.rcParams.update({'font.family': family, 'font.size':11, 'axes.labelsize':11,
    'xtick.labelsize':11, 'ytick.labelsize':11, 'legend.fontsize':10,
    'text.color':'black', 'axes.labelcolor':'black', 'xtick.color':'black',
    'ytick.color':'black', 'axes.edgecolor':'black', 'axes.linewidth':.7,
    'grid.color':'#D5D8DC', 'grid.linewidth':.6, 'pdf.fonttype':42,
    'ps.fonttype':42, 'svg.fonttype':'none', 'savefig.transparent':True,
    'mathtext.fontset':'stix'})

def finish(fig,name):
    for ext in ('pdf','svg','png'):
        fig.savefig(OUT / (name+'.'+ext), transparent=True, dpi=220)
    plt.close(fig)

# Absolute adaptation time, including normal-cache input handling and training.
fig,ax=plt.subplots(figsize=(6.55,2.65))
fig.subplots_adjust(left=.105,right=.975,bottom=.19,top=.92)
methods=['5–16','8–64','E2E']; colors=['#4DBEEE','#0072BD','#D95319']
for j,(method,color) in enumerate(zip(methods,colors)):
    yy=[next(r['seconds'] for r in TIMING if r['scenario']==s and r['method']==method) for s in ['A2B','A2C']]
    xx=np.arange(2)+(j-1)*.23
    ax.bar(xx,yy,width=.205,color=color,edgecolor='black',linewidth=.45,
        hatch=['//','','..'][j],label=('FastSET ('+method+')') if method!='E2E' else method,zorder=3)
    for x,y in zip(xx,yy):ax.annotate(f'{y:.3f}',(x,y),xytext=(0,4),textcoords='offset points',ha='center',fontsize=10)
ax.set_yscale('log');ax.set_ylim(.07,65);ax.set_yticks([.1,1,10]);ax.yaxis.set_major_formatter(FuncFormatter(lambda v,p:f'{v:g}'))
ax.set_xticks([0,1],['A2B','A2C']);ax.set_xlabel('Channel transition');ax.set_ylabel('Adaptation time (s)')
ax.grid(axis='y',which='major');ax.set_axisbelow(True)
ax.legend(loc='upper left',ncol=3,frameon=False,handlelength=1.1,columnspacing=1.5,borderpad=.1)
finish(fig,'architecture_adaptation_time')

# Each alpha reselects the best qualifying checkpoint, as in the current paper.
reference=next(r for r in PEBS_CHECKPOINTS if r['candidate']=='CNN')
a=np.linspace(0,1,1001)
styles=[('d5_w16','5–16','#4DBEEE','-.','v'),('d8_w64','8–64','#0072BD','-','o'),
        ('d6_w64','6–64','#EDB120','--','^'),('d4_w64','4–64','#7E2F8E','-.','D'),
        ('d9_w32','9–32','#77AC30',':','s')]
fig,ax=plt.subplots(figsize=(6.55,2.85))
fig.subplots_adjust(left=.105,right=.975,bottom=.19,top=.95)
alpha_rows=[]
for candidate,label,color,ls,marker in styles:
    rr=[r for r in PEBS_CHECKPOINTS if r['candidate']==candidate]
    scores=np.array([a*float(reference['val2_ber'])/float(r['val2_ber'])+(1-a)*float(reference['total_seconds'])/float(r['total_seconds']) for r in rr])
    curve=scores.max(axis=0)
    ax.plot(a,curve,color=color,ls=ls,marker=marker,markevery=100,ms=4,mfc='white',lw=2,label=label)
    for i,weight in enumerate(a):alpha_rows.append(dict(candidate=candidate,alpha=float(weight),pebs=float(curve[i])))
ax.plot(a,np.ones_like(a),color='#D95319',ls='--',marker='s',markevery=100,ms=4,mfc='white',lw=1.7,label='E2E')
ax.axvline(.8,ymax=.72,color='black',ls=':',lw=.8,zorder=0)
ax.set(xlabel=r'PEBS weight $\alpha$',ylabel='PEBS',xlim=(0,1),ylim=(0,95))
ax.set_xticks(np.arange(0,1.01,.2));ax.set_yticks([0,20,40,60,80]);ax.grid(True);ax.set_axisbelow(True)
ax.legend(loc='upper right',ncol=3,frameon=False,columnspacing=1.0,handlelength=2,borderpad=.2)
finish(fig,'architecture_pebs_alpha')
for name,rr in [('adaptation_times',TIMING),('alpha_sweep',alpha_rows)]:
    with (OUT/(name+'.csv')).open('w') as f:
        w=csv.DictWriter(f,fieldnames=list(dict.fromkeys(k for r in rr for k in r)));w.writeheader();w.writerows(rr)
print('Figures and CSVs written to',OUT)
